package dev.atqiya.ledgerly.invoicing.api;
import dev.atqiya.ledgerly.identity.application.AuthenticatedUser; import dev.atqiya.ledgerly.invoicing.application.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/workspaces/{workspaceId}") public class InvoicingController{
 private final InvoicingService service;public InvoicingController(InvoicingService s){service=s;}
 @PostMapping("/customers") public ResponseEntity<CustomerView> customer(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@Valid @RequestBody InvoicingRequests.CreateCustomer r){var result=service.createCustomer(u.id(),workspaceId,r.name(),r.email(),r.phone(),r.billingAddress());return ResponseEntity.status(HttpStatus.CREATED).body(result);}
 @GetMapping("/customers") public List<CustomerView> customers(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId){return service.customers(u.id(),workspaceId);}
 @PostMapping("/customers/{customerId}/archive") public void archiveCustomer(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@PathVariable UUID customerId){service.archiveCustomer(u.id(),workspaceId,customerId);}
 @PostMapping("/invoices") public ResponseEntity<InvoiceView> invoice(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@Valid @RequestBody InvoicingRequests.CreateInvoice r){var lines=r.lines().stream().map(l->new InvoicingService.NewLine(l.description(),l.quantity(),l.unitPrice())).toList();return ResponseEntity.status(HttpStatus.CREATED).body(service.createInvoice(u.id(),workspaceId,r.customerId(),r.invoiceNumber(),r.issueDate(),r.dueDate(),r.notes(),lines));}
 @GetMapping("/invoices") public List<InvoiceView> invoices(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@RequestParam(required=false) Boolean overdue){return service.list(u.id(),workspaceId,overdue);}
 @PostMapping("/invoices/{invoiceId}/send") public InvoiceView send(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@PathVariable UUID invoiceId){return service.send(u.id(),workspaceId,invoiceId);}
 @PostMapping("/invoices/{invoiceId}/payments") public InvoiceView pay(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@PathVariable UUID invoiceId,@Valid @RequestBody InvoicingRequests.Payment r){return service.pay(u.id(),workspaceId,invoiceId,r.amount(),r.paidOn(),r.reference());}
 @PostMapping("/invoices/{invoiceId}/void") public InvoiceView voidInvoice(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable UUID workspaceId,@PathVariable UUID invoiceId){return service.voidInvoice(u.id(),workspaceId,invoiceId);}
}
